-- Production promotion equivalent of QA-applied 20260922040000.
-- Keep that historical file immutable and EXCLUDE it from the explicit
-- Production manifest. This copy differs only by stable natural-key ordering
-- for the 35 new mapping identities and the explanatory header.
-- A-02 deterministic replay correction.
-- This migration preserves the independently reviewed QA mapping outcome
-- (72 existing mappings annotated, 35 specific sub-control mappings added)
-- without relying on environment-specific surrogate IDs. Stable business
-- keys are used throughout: requirement_code + framework code + control_code.
-- The manifest is validated before any write; missing prerequisites abort the
-- transaction. No mapping is deleted or deactivated, and this migration does
-- not implement the later A-03 superseded-mapping remediation.
--
-- Idempotency:
--   * annotations are appended only when the review marker is absent;
--   * inserts use the existing (requirement_id, control_id) uniqueness rule.
--
begin;
create temporary table a02_mapping_review (
  requirement_code text not null,
  framework_code text not null,
  control_code text not null,
  coverage_type text not null,
  mapping_confidence text not null,
  review_note text not null,
  kind text not null check (kind in ('update','insert')),
  primary key (requirement_code, framework_code, control_code)
) on commit drop;

