do $a02$
declare
  missing_requirements integer;
  missing_controls integer;
  missing_updates integer;
begin
  if (select count(*) from a02_mapping_review) <> 107
     or (select count(*) from a02_mapping_review where kind = 'update') <> 72
     or (select count(*) from a02_mapping_review where kind = 'insert') <> 35 then
    raise exception 'A-02 mapping manifest cardinality mismatch';
  end if;

  select count(*) into missing_requirements
  from a02_mapping_review m
  left join public.cybersecurity_requirements r on r.requirement_code = m.requirement_code
  where r.id is null;

  select count(*) into missing_controls
  from a02_mapping_review m
  left join public.frameworks f on f.code = m.framework_code
  left join public.controls c on c.framework_id = f.id and c.control_code = m.control_code
  where c.id is null;

  select count(*) into missing_updates
  from a02_mapping_review m
  join public.cybersecurity_requirements r on r.requirement_code = m.requirement_code
  join public.frameworks f on f.code = m.framework_code
  join public.controls c on c.framework_id = f.id and c.control_code = m.control_code
  left join public.cybersecurity_requirement_controls rc
    on rc.requirement_id = r.id and rc.control_id = c.id
  where m.kind = 'update' and rc.id is null;

  if missing_requirements <> 0 or missing_controls <> 0 or missing_updates <> 0 then
    raise exception 'A-02 mapping prerequisites missing: requirements=%, controls=%, update mappings=%',
      missing_requirements, missing_controls, missing_updates;
  end if;
end
$a02$;

update public.cybersecurity_requirement_controls rc
set notes = coalesce(rc.notes || E'\n', '') || m.review_note
from a02_mapping_review m
join public.cybersecurity_requirements r on r.requirement_code = m.requirement_code
join public.frameworks f on f.code = m.framework_code
join public.controls c on c.framework_id = f.id and c.control_code = m.control_code
where m.kind = 'update'
  and rc.requirement_id = r.id
  and rc.control_id = c.id
  and (rc.notes is null or rc.notes not like '%[Master-Catalog review 2026-09-21]%');

insert into public.cybersecurity_requirement_controls
  (requirement_id, control_id, coverage_type, mapping_confidence, notes)
select r.id, c.id, m.coverage_type, m.mapping_confidence, m.review_note
from a02_mapping_review m
join public.cybersecurity_requirements r on r.requirement_code = m.requirement_code
join public.frameworks f on f.code = m.framework_code
join public.controls c on c.framework_id = f.id and c.control_code = m.control_code
where m.kind = 'insert'
order by m.requirement_code, m.framework_code, m.control_code
on conflict (requirement_id, control_id) do nothing;

commit;
